class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        if len(s1) > len(s2):
            return False

        need = {}
        for c in s1:
            need[c] = 1 + need.get(c, 0)

        window = {}
        matches = 0
        l = 0

        for r in range(len(s2)):
            if s2[r] in need:
                window[s2[r]] = 1 + window.get(s2[r], 0)
                if window[s2[r]] == need[s2[r]]:
                    matches += 1
                elif window[s2[r]] == need[s2[r]] + 1:
                    matches -= 1

            if r - l + 1 > len(s1):
                if s2[l] in need:
                    window[s2[l]] -= 1
                    if window[s2[l]] == need[s2[l]]:
                        matches += 1
                    elif window[s2[l]] == need[s2[l]] - 1:
                        matches -= 1
                l += 1

            if matches == len(need):
                return True

        return False

